#!/usr/bin/env bash
# ============================================================
#  aria-relay-panel  v1.4.0 installer (build rfix2, no changes)
#  Deploys the EXACT current server.js build (embedded base64).
# ============================================================
set -euo pipefail
umask 027

if [ "$(id -u)" -ne 0 ]; then
  echo "[*] not root -> re-running with sudo"
  if ! command -v sudo >/dev/null 2>&1; then
    echo "!! root required (or install sudo first)" >&2
    exit 1
  fi
  if [ "${0#-}" != "$0" ] || [ ! -f "$0" ]; then
    echo "!! save the script first: curl ... -o install.sh && sudo bash install.sh" >&2
    exit 1
  fi
  exec sudo -E bash "$0"
fi

DEST="/opt/aria-panel"
ENVF="/etc/aria-panel.env"
SVC="aria-panel"

echo "[*] aria-relay-panel installer"

# ---------- 1) Node.js >= 18 ----------
NEED_NODE=1
if command -v node >/dev/null 2>&1; then
  NM=$(node -p 'process.versions.node.split(".")[0]' 2>/dev/null || echo 0)
  if [ "${NM:-0}" -ge 18 ]; then NEED_NODE=0; fi
fi
if [ "$NEED_NODE" = "1" ]; then
  echo "[*] installing Node.js 20 ..."
  if command -v apt-get >/dev/null 2>&1; then
    export DEBIAN_FRONTEND=noninteractive
    apt-get update -qq
    apt-get install -y -qq ca-certificates curl gnupg >/dev/null
    curl -fsSL https://deb.nodesource.com/setup_20.x | bash - >/dev/null
    apt-get install -y -qq nodejs >/dev/null
  else
    echo "!! no apt-get: install Node.js 18+ manually, then re-run this script" >&2
    exit 1
  fi
fi
echo "[*] node: $(node -v), npm: $(npm -v 2>/dev/null || echo '?')"

# ---------- 2) unpack panel ----------
mkdir -p "$DEST"
echo "Y29uc3QgaHR0cCA9IHJlcXVpcmUoImh0dHAiKTsKY29uc3QgbmV0ID0gcmVxdWlyZSgibmV0Iik7
