Owo=
" | base64 -d > "$DEST/server.js"
if ! node --check "$DEST/server.js" 2>/dev/null; then
  echo "!! unpacked server.js failed syntax check" >&2; exit 1
fi

cat > "$DEST/package.json" <<'PKG'
{
  "name": "aria-relay-panel",
  "version": "1.4.0",
  "private": true,
  "main": "server.js",
  "engines": { "node": ">=18" },
  "scripts": { "start": "node server.js" },
  "dependencies": {
    "pg": "^8.23.1",
    "ws": "^8.22.0"
  }
}
PKG

echo "[*] npm install ..."
( cd "$DEST" && npm install --omit=dev --no-audit --no-fund --loglevel=error )

# ---------- 3) env file ----------
if [ ! -f "$ENVF" ]; then
  SITE_KEY=$(node -e "console.log(require('crypto').randomBytes(16).toString('hex'))")
  ADMIN_PASS=$(node -e "console.log(require('crypto').randomBytes(18).toString('base64url'))")
  cat > "$ENVF" <<EOF
# aria-relay-panel environment
SITE_KEY=$SITE_KEY
ADMIN_PASS=$ADMIN_PASS
ADMIN_PATH=stock-manage
# MUST equal the key embedded in the Android app or mo:// codes will not decode
CONFIG_KEY=6de428f0d6ea2427d4a3d0d4f601635b95fe9af245920978
DATABASE_URL=
# set to your public URL (https://domain or http://IP:PORT); files fetch from Host otherwise
WORKER_URL=
PORT=8080
V2_DISABLE=
EOF
  chmod 640 "$ENVF"
else
  echo "[*] $ENVF already exists - keeping current config"
fi
set -a; . "$ENVF"; set +a

# ---------- 4) run ----------
if command -v systemctl >/dev/null 2>&1; then
  cat > "/etc/systemd/system/$SVC.service" <<EOF
[Unit]
Description=aria-relay-panel (v1 WS + v2 devsync + hidden panel)
After=network.target

[Service]
WorkingDirectory=$DEST
EnvironmentFile=$ENVF
ExecStart=$(command -v node) $DEST/server.js
Restart=always
RestartSec=3

[Install]
WantedBy=multi-user.target
EOF
  systemctl daemon-reload
  systemctl enable --now "$SVC" 2>/dev/null || systemctl restart "$SVC"
  RUNINFO="systemctl status $SVC   (logs: journalctl -u $SVC -f)"
else
  echo "[*] no systemd - running with nohup"
  ( cd "$DEST" && nohup node server.js > "$DEST/panel.log" 2>&1 & )
  CRON="@reboot sleep 5; cd $DEST && env \$(grep -v '^#' $ENVF | xargs) node server.js >> $DEST/panel.log 2>&1"
  ( crontab -l 2>/dev/null | grep -v "$DEST/server.js"; echo "$CRON" ) | crontab - >/dev/null 2>&1 || true
  RUNINFO="tail -f $DEST/panel.log"
fi

# ---------- 5) firewall hint ----------
if command -v ufw >/dev/null 2>&1; then ufw allow ${PORT:-8080}/tcp >/dev/null 2>&1 || true; fi

sleep 1
echo ""
echo "========================================================"
echo "  DONE.  admin panel:  http://<server-ip>:$PORT/$ADMIN_PATH"
echo "           admin pass: $ADMIN_PASS"
echo "           master key: $SITE_KEY"
echo "  config:  $ENVF   |   change var -> restart service"
echo "  logs:    $RUNINFO"
echo "  check:   curl -s -X POST http://127.0.0.1:$PORT/v1/handshake  -> {\"ok\":1}"
echo "========================================================"
